<?php if($errors): ?><div class="alert alert-error"><?php foreach($errors as $list): foreach((array)$list as $err): ?><div><?= e($err) ?></div><?php endforeach; endforeach; ?></div><?php endif; ?>
<div class="card table-card"><div class="table-scroll"><table class="table"><thead><tr><th>Payment</th><th>Customer</th><th>Quote</th><th>Amount</th><th>M-Pesa</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><strong><?= e($p['payment_reference']) ?></strong><br><span class="muted-small">Submitted</span></td><td><?= e($p['name']) ?><br><span class="muted-small"><?= e($p['phone']) ?></span></td><td><?= e($p['quote_number']) ?></td><td><strong>KES <?= e(number_format((float)$p['amount'],2)) ?></strong></td><td><?= e($p['mpesa_receipt']) ?><br><span class="muted-small"><?= e($p['payer_phone'] ?: '—') ?></span></td><td><?= e(date('d M Y, H:i',strtotime($p['created_at']))) ?></td><td><form method="POST" action="<?= e($adminPath) ?>/assistance/payments/<?= (int)$p['id'] ?>/verify" style="display:inline"><?= csrf_field() ?><button class="btn btn-primary btn-sm" type="submit">Verify</button></form> <details class="inline-details"><summary class="btn btn-secondary btn-sm">Reject</summary><form method="POST" action="<?= e($adminPath) ?>/assistance/payments/<?= (int)$p['id'] ?>/reject" class="inline-reject"><?= csrf_field() ?><input name="reason" maxlength="500" placeholder="Reason"><button class="btn btn-danger btn-sm" type="submit">Confirm</button></form></details></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="7" class="empty-table">No payments are waiting for verification.</td></tr><?php endif; ?></tbody></table></div></div>
